#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# M5 acceptance: Flow A change intake, live on Pro as rnship-agent, against the private
# fixture app with M3's hand-approved baseline (design §7 M5):
#   1  settings-screen adds a screen: go, A5 tasks that lint, a smoke flow per user-facing AC
#   2  tank-photo adds the camera: a baseline delta; A5 refuses before you approve, and once
#      approved, tick's prep installs expo-camera with its lockfile before any task
#   3  carplay-dashboard: stop, citing suitability.carplay
#   4  daily-streak cites research with an injected instruction: no line reaches a prompt
#   5  editing settings-screen after approval holds its run; reverting releases it
# Model calls: one Haiku preflight, then Sonnet for A2/A4 of four changes and A5 of two
# (about 10 calls). Ticks use the fake executor: implementation isn't under test here, and
# it spends no quota. Run as YOUR macOS user after m3.sh (it reuses M3's agent setup,
# compiled settings, fixture baseline and approval). Results: docs/spikes/M5.results.env.

ROOT=$(cd "$(dirname "$0")/../.." && pwd)
PIPELINE_URL=$(git -C "$ROOT" remote get-url origin | sed -E 's#^git@([^:]+):#https://\1/#; s#\.git$##')
AGENT=${RNSHIP_AGENT_USER:-rnship-agent}
AGENT_HOME=$(dscl . -read "/Users/$AGENT" NFSHomeDirectory 2>/dev/null | awk '{print $2}')
AGENT_HOME=${AGENT_HOME:-/Users/$AGENT}
AGENT_RNSHIP=$AGENT_HOME/rnship
AGENT_PATH=$AGENT_RNSHIP/node_modules/.bin:$AGENT_HOME/.local/node/bin:$AGENT_HOME/.local/bin:/usr/bin:/bin:/usr/sbin:/sbin
M3_SHARED=/Users/Shared/rnship-m3 # M3's compiled executor settings (yours, read-only to the agent)
SETTINGS=$M3_SHARED/build/executor-settings.json
SHARED=/Users/Shared/rnship-m5    # logs, scripts and your copy of the baseline (yours, group $AGENT, 1770)
STATE=/Users/Shared/rnship-state  # approval records: yours, 755
WORK=${RNSHIP_FIXTURE_DIR:-$HOME/Home_Projects/rnship-s6-probe}
APP=$AGENT_HOME/apps/m5
CHANGES=$APP/.rnship/changes
DB=$AGENT_HOME/.rnship/m5/orchestrator.db
ENV_FILE=$ROOT/docs/spikes/M5.results.env
CHANGE_IDS=(settings-screen tank-photo carplay-dashboard daily-streak)
VALIDATE='sh .rnship/validate.sh'

trap 'warn "stopped at line $LINENO. Fix the cause and re-run; finished stages are safe to repeat."' ERR

record() { write_env "$1" "$2"; }
UNATTENDED=no
notify() {
  printf '\a'
  osascript -e 'on run argv' -e 'display notification (item 1 of argv) with title "rnship M5"' -e 'end run' "$1" \
    >/dev/null 2>&1 || true
}
fail() { warn "$1"; [[ $UNATTENDED == yes ]] && notify "Stopped: $1"; exit 1; }
rnship() { node "$ROOT/cli/src/main.ts" "$@"; } # yours, for approvals
as_agent() {
  ( cd / && sudo -u "$AGENT" -H /usr/bin/env PATH="$AGENT_PATH" RNSHIP_STATE_DIR="$STATE" RNSHIP_DB="$DB" "$@" )
}
as_agent_sh() { as_agent /bin/sh -c "cd ~ && $1"; }
sql() { local out; out=$(as_agent /usr/bin/sqlite3 -json "$DB" "$1"); echo "${out:-[]}"; }
var_of() { tr 'a-z-' 'A-Z_' <<<"$1"; } # tank-photo → TANK_PHOTO
session_up() {
  sudo launchctl print "gui/$AGENT_UID" >/dev/null 2>&1 \
    && sudo test -e "$AGENT_HOME/Library/Keychains/login.keychain-db"
}
# tick_fake: one orchestrator pass with the fake executor, outside the GUI session (no Claude).
tick_fake() { as_agent rnship tick --executor fake --fake-script "$SHARED/fake.json"; }

# in_session LABEL TIMEOUT CMD... runs CMD once as a LaunchAgent in the agent's GUI session,
# where its keychain holds the Claude login. Output goes to $SHARED/LABEL.log.
in_session() {
  local label=$1 timeout=$2; shift 2
  local job="dev.rnship.m5.$label"
  local plist="$AGENT_HOME/Library/LaunchAgents/$job.plist"
  local log="$SHARED/$label.log" done="$SHARED/$label.done" arg args="" waited=0
  for arg in "$@"; do args+="<string>$arg</string>"; done
  sudo rm -f "$log" "$done"
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo -u "$AGENT" mkdir -p "$AGENT_HOME/Library/LaunchAgents"
  sudo -u "$AGENT" tee "$plist" >/dev/null <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$job</string>
  <key>ProgramArguments</key><array>
    <string>/bin/sh</string><string>-c</string><string>"\$@"; touch $done</string><string>sh</string>$args
  </array>
  <key>EnvironmentVariables</key><dict>
    <key>PATH</key><string>$AGENT_PATH</string>
    <key>RNSHIP_STATE_DIR</key><string>$STATE</string>
    <key>RNSHIP_DB</key><string>$DB</string>
  </dict>
  <key>RunAtLoad</key><true/>
  <key>StandardOutPath</key><string>$log</string>
  <key>StandardErrorPath</key><string>$log</string>
</dict></plist>
PLIST
  if sudo launchctl bootstrap "gui/$AGENT_UID" "$plist"; then
    note "running in $AGENT's session (up to $((timeout / 60)) min); log: $log"
    while [[ ! -e "$done" ]] && (( waited < timeout )); do
      sleep 5; waited=$((waited + 5))
      (( waited % 60 == 0 )) && note "$((waited / 60)) min…"
    done
  else
    warn "bootstrap failed: is $AGENT still logged in (fast user switching)?"
  fi
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo rm -f "$plist"
  [[ -e "$done" ]]
}

TOTAL_STAGES=8

banner "M5: Flow A change intake as $AGENT"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
[[ $EUID -ne 0 && "$(id -un)" != "$AGENT" ]] || fail "run this as your own macOS user"
for c in jq git node sudo; do command -v "$c" >/dev/null || fail "missing $c"; done
node -e 'process.exit(+process.versions.node.split(".")[0] >= 24 ? 0 : 1)' || fail "need Node 24 (nvm use 24)"
say "sudo runs every step as $AGENT; enter your password once."
sudo -v
while sleep 60; do sudo -n true 2>/dev/null || exit; done &
SUDO_KEEPALIVE=$!
trap 'kill "$SUDO_KEEPALIVE" 2>/dev/null || true' EXIT
AGENT_UID=$(id -u "$AGENT" 2>/dev/null) || fail "no $AGENT user: run scripts/spikes/s0-identity.sh first"
session_up || fail "$AGENT isn't logged in: log in once (user switcher), switch back, re-run"
[[ -r "$SETTINGS" ]] || fail "no $SETTINGS: run scripts/acceptance/m3.sh (through stage 5) first"
git -C "$ROOT" fetch -q origin main
[[ -z "$(git -C "$ROOT" status --porcelain)" ]] || fail "uncommitted changes in $ROOT: the agent runs what's on origin/main"
RNSHIP_SHA=$(git -C "$ROOT" rev-parse origin/main)
[[ "$(git -C "$ROOT" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "HEAD isn't origin/main: git push origin main (or pull) first"
[[ -d "$WORK/.git" && -f "$WORK/.rnship/approved-baseline.yaml" && -f "$WORK/.rnship/validate.sh" ]] \
  || fail "no M3 baseline and validate.sh in $WORK (m3.sh stage 4)"
cd "$WORK" && git fetch -q origin && git switch -q main && git pull -q --ff-only origin main && cd "$ROOT"
APPROVED=$( (RNSHIP_STATE_DIR=$STATE rnship policy check "$WORK" --base-ref HEAD || true) | jq -r '.baseline.approved')
[[ "$APPROVED" == true ]] || fail "$WORK's baseline isn't approved in $STATE (m3.sh stage 4)"
APP_ID=$(cd "$WORK" && npx --no-install expo config --json 2>/dev/null | jq -r '.ios.bundleIdentifier // .android.package // empty')
[[ -n "$APP_ID" ]] || fail "couldn't read the fixture's bundle identifier from expo config"
mkdir -p "$SHARED" && sudo chown "$(id -un):$AGENT" "$SHARED" && chmod 1770 "$SHARED"
echo '{}' > "$SHARED/fake.json" && chmod 644 "$SHARED/fake.json"
record M5_RNSHIP_SHA "$RNSHIP_SHA"
record M5_FIXTURE_SHA "$(git -C "$WORK" rev-parse HEAD)"
say "The agent will run rn-ship-pipeline@${RNSHIP_SHA:0:12}. About 10 Sonnet calls and one Haiku call."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "rn-ship-pipeline for $AGENT"
if sudo test -d "$AGENT_RNSHIP/.git"; then as_agent git -C "$AGENT_RNSHIP" fetch -q origin main; else as_agent git clone -q "$PIPELINE_URL" "$AGENT_RNSHIP"; fi
as_agent git -C "$AGENT_RNSHIP" checkout -q --detach "$RNSHIP_SHA"
as_agent_sh "cd rnship && npx -y pnpm@10.30.0 install --frozen-lockfile --reporter=silent"
[[ "$(as_agent git -C "$AGENT_RNSHIP" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "the agent's checkout isn't at $RNSHIP_SHA"
say "Installed in $AGENT_RNSHIP."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fixture clone and the four change requests"
if sudo test -e "$APP" || sudo test -e "$(dirname "$DB")"; then
  say "An earlier M5 run left ~/apps/m5 or ~/.rnship/m5."
  confirm "Delete them and start fresh?" || fail "stopped; move them aside and re-run"
  as_agent rm -rf "$APP" "$(dirname "$DB")"
fi
BUNDLE=$SHARED/fixture.bundle
rm -f "$BUNDLE" && git -C "$WORK" bundle create "$BUNDLE" main 2>/dev/null && chmod 644 "$BUNDLE"
as_agent git clone -q -b main "$BUNDLE" "$APP"
as_agent git -C "$APP" config user.name "$AGENT"
as_agent git -C "$APP" config user.email "$AGENT@localhost"
note "npm ci in ~/apps/m5…"
as_agent_sh "cd apps/m5 && npm ci --no-audit --no-fund --loglevel=error"
for id in "${CHANGE_IDS[@]}"; do
  as_agent mkdir -p "$CHANGES/$id"
  as_agent cp -R "$AGENT_RNSHIP/fixtures/changes/$id/." "$CHANGES/$id/"
  as_agent rm -f "$CHANGES/$id/stub-answers.json"
done
say "Copied fixtures/changes/{${CHANGE_IDS[*]}} into ~/apps/m5/.rnship/changes/."
note "Read them in $ROOT/fixtures/changes/ if you like: those are the needs Claude gets."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
# The intake stages are tool-less `claude -p --json-schema` calls. Nothing has run that flag
# as the agent on Pro yet, so one Haiku call checks it with the real flags first.
stage "--json-schema preflight (one Haiku call)"
PRE=$SHARED/preflight.jsonl
cat > "$SHARED/m5-preflight.sh" <<RUN
#!/bin/sh
cd "\$HOME" || exit 1
echo 'Reply with ok set to true.' | claude -p --model claude-haiku-5-5 --tools '' \\
  --json-schema '{"type":"object","properties":{"ok":{"type":"boolean"}},"required":["ok"],"additionalProperties":false}' \\
  --output-format stream-json --verbose --permission-mode dontAsk --plugin-dir "$AGENT_RNSHIP/plugin" \\
  --settings "$SETTINGS" --setting-sources user > "$PRE"
echo "claude exit=\$?"
RUN
chmod 755 "$SHARED/m5-preflight.sh"
in_session preflight 300 /bin/sh "$SHARED/m5-preflight.sh" || fail "the preflight didn't finish: see $SHARED/preflight.log"
STRUCTURED=$(jq -rs 'map(select(.type == "result"))[-1] | if .structured_output.ok == true then "structured_output" elif ((.result // "") | test("\"ok\"\\s*:\\s*true")) then "result_text" else "no" end' "$PRE")
GUARD=$(jq -rs 'map(select(.type == "system" and .subtype == "init"))[0].plugins // [] | map(.name) | if index("rnship") then "yes" else "no" end' "$PRE")
record M5_PREFLIGHT_JSON "$STRUCTURED"
record M5_PREFLIGHT_GUARD "$GUARD"
note "Wanted: JSON structured_output (result_text works too), guard yes."
[[ "$STRUCTURED" != no && "$GUARD" == yes ]] || fail "preflight: json=$STRUCTURED guard=$GUARD. Read $PRE before spending Sonnet."
pause "Press Enter to run intake on the four changes (unattended, a few minutes)"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Intake (A1–A4) on the four changes"
UNATTENDED=yes
cat > "$SHARED/m5-intake.sh" <<RUN
#!/bin/sh
# m5-intake.sh ID…: rnship change intake for each change, as $AGENT in its GUI session.
cd "\$HOME" || exit 1
for id in "\$@"; do
  rnship change intake "$CHANGES/\$id" --repo "$APP" --settings "$SETTINGS" > "$SHARED/intake-\$id.json"
  echo "\$id exit=\$?"
done
RUN
chmod 755 "$SHARED/m5-intake.sh"
in_session intake 1800 /bin/sh "$SHARED/m5-intake.sh" "${CHANGE_IDS[@]}" || fail "intake didn't finish: see $SHARED/intake.log"
sed 's/^/    /' "$SHARED/intake.log" | tail -n 12
for id in "${CHANGE_IDS[@]}"; do
  out=$SHARED/intake-$id.json; v=M5_$(var_of "$id")
  if [[ -s "$out" ]] && jq -e . "$out" >/dev/null 2>&1; then
    record "${v}_VERDICT" "$(jq -r .verdict "$out")"
    record "${v}_RULES" "$(jq -r '.impact.rule_hits | map(.ruleId) | join(",")' "$out")"
    record "${v}_INSTALL" "$(jq -r '.impact.install | join(",")' "$out")"
    record "${v}_DELTA" "$(jq -c .delta "$out")"
  else
    record "${v}_VERDICT" "error: $(grep -v '^ *$' "$SHARED/intake.log" | grep -m1 -i "$id\|error" | cut -c1-200)"
  fi
done
# Case 4: no line of the research file in any prompt an intake session got.
LEAKS=$(as_agent node --input-type=module -e '
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { researchLines } from "'"$AGENT_RNSHIP"'/orchestrator/src/index.ts";
const lines = researchLines(readFileSync(process.argv[1], "utf8"));
const dir = process.argv[2];
let leaks = 0, prompts = 0;
for (const s of readdirSync(dir)) {
  const p = readFileSync(join(dir, s, "prompt.md"), "utf8").toLowerCase().replace(/\s+/g, " ");
  prompts++;
  leaks += lines.filter((l) => p.includes(l)).length + (p.includes("attacker.example") ? 1 : 0);
}
console.log(`${leaks} in ${prompts} prompts`);' "$CHANGES/daily-streak/research/notes.md" "$AGENT_HOME/.rnship/m5/intake")
record M5_RESEARCH_LEAKS "$LEAKS"
UNATTENDED=no
grep '^M5_' "$ENV_FILE" | grep -v 'SHA=\|PREFLIGHT' | sed 's/^/    /'
note "Wanted: SETTINGS_SCREEN go · TANK_PHOTO go-dev-build, rules permissions.native + deps.upgrade,"
note "install expo-camera@… · CARPLAY_DASHBOARD stop, suitability.carplay · DAILY_STREAK go · LEAKS 0 in N."
note "A model may reasonably propose an extra package for settings-screen (go-dev-build); read DELTA."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Case 2: A5 refuses tank-photo before you approve"
REFUSED=$(as_agent rnship change tasks "$CHANGES/tank-photo" --app m5-camera --repo "$APP" --settings "$SETTINGS" \
  --validation "$VALIDATE" --app-id "$APP_ID" 2>&1 || true)
record M5_CAMERA_BEFORE_APPROVAL "$(grep -q 'A5 refuses' <<<"$REFUSED" && echo refused || echo "not refused: $(head -c 200 <<<"$REFUSED")")"
record M5_CAMERA_RUNS_BEFORE_APPROVAL "$(sql "SELECT count(*) AS n FROM runs" | jq -r '.[0].n')"
note "Wanted: refused, 0 runs."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Your approvals: settings-screen and tank-photo"
cp "$WORK/.rnship/approved-baseline.yaml" "$SHARED/baseline.yaml" && chmod 644 "$SHARED/baseline.yaml"
REVIEW=$(mktemp -d)
for id in settings-screen tank-photo; do
  [[ "$(jq -r .verdict "$SHARED/intake-$id.json" 2>/dev/null)" =~ ^go ]] || fail "$id has no go verdict; see stage 5"
  # The agent's home is closed to you; review and approve a copy (the digest is of the content).
  sudo tar -C "$CHANGES" -cf - --exclude tasks "$id" | tar -C "$REVIEW" -xf -
  say "$id:"
  RNSHIP_STATE_DIR=$STATE rnship change status "$REVIEW/$id" --repo "$WORK" | jq '{verdict, rule_hits, install, baseline_delta, digest}' | sed 's/^/    /'
  note "screens.yaml: $REVIEW/$id/screens.yaml"
  confirm "Approve $id at this digest?" || fail "stopped; nothing approved for $id"
  RNSHIP_STATE_DIR=$STATE rnship change approve "$REVIEW/$id" "$(jq -r .digest "$SHARED/intake-$id.json")" \
    --baseline "$SHARED/baseline.yaml" --project "$WORK" | sed 's/^/    /'
done
# The agent's repo needs the baseline with the camera delta; its approval is yours, by digest.
sudo -u "$AGENT" tee "$APP/.rnship/approved-baseline.yaml" < "$SHARED/baseline.yaml" >/dev/null
note "Your merged baseline: $SHARED/baseline.yaml (commit it to the fixture when you keep the camera change)."
pause "Press Enter to run A5 on both (unattended, a few minutes)"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "A5, then the change gate under the fake executor"
UNATTENDED=yes
cat > "$SHARED/m5-tasks.sh" <<RUN
#!/bin/sh
cd "\$HOME" || exit 1
rnship change tasks "$CHANGES/settings-screen" --app m5-settings --repo "$APP" --settings "$SETTINGS" --validation "$VALIDATE" --app-id "$APP_ID" > "$SHARED/tasks-settings-screen.json"
echo "settings-screen exit=\$?"
rnship change tasks "$CHANGES/tank-photo" --app m5-camera --repo "$APP" --settings "$SETTINGS" --validation "$VALIDATE" --app-id "$APP_ID" > "$SHARED/tasks-tank-photo.json"
echo "tank-photo exit=\$?"
RUN
chmod 755 "$SHARED/m5-tasks.sh"
in_session tasks 1800 /bin/sh "$SHARED/m5-tasks.sh" || fail "A5 didn't finish: see $SHARED/tasks.log"
sed 's/^/    /' "$SHARED/tasks.log" | tail -n 6
for id in settings-screen tank-photo; do
  out=$SHARED/tasks-$id.json; v=M5_$(var_of "$id")
  record "${v}_A5" "$(jq -r '"tasks=\(.created | length) flows=\(.flows | join("+"))"' "$out" 2>/dev/null || echo "error: see $SHARED/tasks.log")"
done
SETTINGS_RUN=$(jq -r .run "$SHARED/tasks-settings-screen.json")
CAMERA_RUN=$(jq -r .run "$SHARED/tasks-tank-photo.json")
[[ "$SETTINGS_RUN" =~ ^[0-9]+$ && "$CAMERA_RUN" =~ ^[0-9]+$ ]] || fail "A5 didn't import both changes; see $SHARED/tasks.log"

# Case 5: an edit after approval holds the settings run; the camera run isn't affected.
REQ=$CHANGES/settings-screen/change-request.yaml
as_agent cp "$REQ" "$REQ.orig"
as_agent /bin/sh -c "printf '# edited after approval\n' >> '$REQ'"
note "tick (fake executor) with settings-screen edited…"
tick_fake > "$SHARED/tick-1.json" 2>"$SHARED/tick-1.log" || true
record M5_EDIT_HOLD "$(sql "SELECT hold FROM runs WHERE id = $SETTINGS_RUN" | jq -r '.[0].hold // "not held"' | cut -c1-160)"
record M5_EDIT_LEASED "$(sql "SELECT count(*) AS n FROM tasks WHERE run_id = $SETTINGS_RUN AND state NOT IN ('pending', 'ready')" | jq -r '.[0].n')"
as_agent mv "$REQ.orig" "$REQ"
note "ticks with the edit reverted (the camera prep runs npm ci + expo install under the sandbox)…"
for i in 2 3 4 5; do
  tick_fake > "$SHARED/tick-$i.json" 2>"$SHARED/tick-$i.log" || true
  [[ "$(sql "SELECT count(*) AS n FROM tasks WHERE run_id IN ($SETTINGS_RUN, $CAMERA_RUN) AND state != 'done'" | jq -r '.[0].n')" == 0 ]] && break
done
record M5_RUN_STATES "$(sql "SELECT r.id AS run, t.key, t.state FROM tasks t JOIN runs r ON r.id = t.run_id ORDER BY t.id" | jq -r 'map("\(.run):\(.key)=\(.state)") | join(",")')"
record M5_RUN_HOLDS "$(sql "SELECT id, hold FROM runs" | jq -r 'map("\(.id):\(.hold // "none")") | join(" | ")' | cut -c1-300)"
CAMERA_WT=$(sql "SELECT worktree FROM runs WHERE id = $CAMERA_RUN" | jq -r '.[0].worktree // empty')
if [[ -n "$CAMERA_WT" ]]; then
  PREP=$(as_agent git -C "$CAMERA_WT" log --format=%H --grep '^chore: prepare change tank-photo' -n1)
  record M5_CAMERA_PREP_FILES "$( [[ -n "$PREP" ]] && as_agent git -C "$CAMERA_WT" show --name-only --format= "$PREP" | grep -E '^(package.json|package-lock.json|smoke/|.rnship/)' | tr '\n' ',' || echo none)"
  record M5_CAMERA_PIN "$(as_agent node -p "require('$CAMERA_WT/package.json').dependencies['expo-camera'] ?? 'missing'")"
fi
UNATTENDED=no

# ── Summary ───────────────────────────────────────────────────────────────
notify "M5 acceptance finished"
finish
grep '^M5_' "$ENV_FILE" | sed 's/^/    /'
say ""
note "Wanted: EDIT_HOLD names the edit · EDIT_LEASED 0 · RUN_STATES all done · RUN_HOLDS none"
note "· CAMERA_PREP_FILES has package.json, package-lock.json, smoke/… · CAMERA_PIN = the approved spec."
say ""
say "Left in place: ~/apps/m5 and ~/.rnship/m5 of $AGENT (prompts under ~/.rnship/m5/intake), $SHARED."
note "Clean up later with: sudo -u $AGENT rm -rf $APP $(dirname "$DB")"
note "Write findings to docs/spikes/M5.md."
printf '\n'
